		const tokens = {
			inputTokens: 0,
			outputTokens: 0,
			cacheCreationTokens: 0,
			cacheReadTokens: 0,
		};

		const total = getTotalTokens(tokens);
		expect(total).toBe(0);
	});

	test('createTotalsObject should create complete totals object', () => {
