			const stats = await detectMismatches(fixture.path);

			expect(stats.totalEntries).toBe(2);
			expect(stats.entriesWithBoth).toBe(0);
			expect(stats.matches).toBe(0);
			expect(stats.mismatches).toBe(0);
		});

